#ifndef MEP_KOTLIN_LSP_H
#define MEP_KOTLIN_LSP_H

// The analysis half of mep's own Kotlin language server (the wire half is
// kotlin_lsp_server.cpp, the `mep-kotlin-lsp` binary; the `kotlin_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (kotlin_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct KotlinLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class KotlinLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const KotlinLspDocument> KotlinLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class KotlinLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct KotlinLspDiagnostic {
    KotlinLspRange range;
    KotlinLspSeverity severity = KotlinLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<KotlinLspDiagnostic> KotlinLspDiagnostics(const KotlinLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string KotlinLspFormatDiagnostic(const std::string &path, const KotlinLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool KotlinLspDiagnosticFails(const KotlinLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class KotlinLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct KotlinLspCompletionItem {
    std::string label;
    std::string insert_text;
    KotlinLspKind kind = KotlinLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<KotlinLspCompletionItem> KotlinLspCompletions(const KotlinLspDocument &doc, int line, int col);

struct KotlinLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    KotlinLspRange range;
};

KotlinLspHoverInfo KotlinLspHover(const KotlinLspDocument &doc, int line, int col);

struct KotlinLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

KotlinLspSignatureHelp KotlinLspSignatureAt(const KotlinLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct KotlinLspLocation {
    KotlinLspRange range;
};

std::vector<KotlinLspLocation> KotlinLspDefinition(const KotlinLspDocument &doc, int line, int col);

struct KotlinLspReference {
    KotlinLspRange range;
    bool is_definition = false;
};

std::vector<KotlinLspReference> KotlinLspReferences(const KotlinLspDocument &doc, int line, int col);

struct KotlinLspTextEdit {
    KotlinLspRange range;
    std::string new_text;
};

struct KotlinLspRenameTarget {
    bool found = false;
    KotlinLspRange range;
    std::string placeholder;
};

KotlinLspRenameTarget KotlinLspPrepareRename(const KotlinLspDocument &doc, int line, int col);
std::vector<KotlinLspTextEdit> KotlinLspRename(const KotlinLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class KotlinLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct KotlinLspSymbol {
    std::string name;
    std::string detail;
    KotlinLspSymbolKind kind = KotlinLspSymbolKind::Variable;
    KotlinLspRange range;
    KotlinLspRange sel_range;
    int parent = -1;
};

std::vector<KotlinLspSymbol> KotlinLspSymbols(const KotlinLspDocument &doc);

struct KotlinLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<KotlinLspFold> KotlinLspFolds(const KotlinLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<KotlinLspTextEdit> KotlinLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_KOTLIN_LSP_H
